import React from 'react';
import { Menu } from 'antd';
import Router from 'next/router';
import MainHead from 'components/IntegratePages/layout/dashboardMenu/head';
import Maintenance from 'components/common/ErrorPages/Maintenance';
import FourHundredFour from 'components/common/ErrorPages/FourHundredFour';
import { errorMessageGlobal, titleByEnv } from 'Utils/constants/index';

const Error = (props) => {
  const { statusCode = 404, isResetError, message, errorMessage } = props
  let PageContent; let statusCodeCopy = statusCode
  if(statusCode === 'custom') statusCodeCopy = 403
  switch (+statusCodeCopy) {
    case 503:
      PageContent = <Maintenance />;
      break;
    case 400:
      PageContent = isResetError ? (
        <div className="error-more link-expired-error">
          <div className="header">
            <div className="container">
              <div className="externalheader">
                <a href={process.env.REDIRECT_URL}>
                  <img
                    src="/static/uxcam-new-logo.svg"
                    alt="UXCam"
                    width="150px"
                  />
                </a>
              </div>
            </div>
          </div>
          <div className="content">
            <div className="container">
              <div className="row">
                <div className="column">
                  <div className="text">
                    <span
                      className="main-number"
                      style={{
                        fontSize: '60px',
                        display: 'block',
                        lineHeight: 'normal',
                        marginBottom: '45px',
                        marginTop: '45px',
                      }}
                    >
                      Invalid link
                    </span>
                    <span
                      className="internal"
                      style={{
                        fontSize: '23px',
                        display: 'block',
                        paddingTop: '15px',
                        margin: '20px 0 0 5px',
                      }}
                    >
                      {message}
                    </span>
                    <a
                      href={process.env.REDIRECT_URL}
                      className="ant-btn btn-home"
                    >
                      Back to dashboard
                    </a>
                  </div>
                </div>
                <div className="column">
                  <img
                    src="/static/error/illustration-link-expired.svg"
                    className="illustration-img"
                    alt="Illustration server down"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      ) : null;
      break;
    case 403:
      PageContent = (
        <div className="error-more custom-error">
          <div className="header">
            <div className="container">
              <div className="externalheader">
                <a href={process.env.REDIRECT_URL}>
                  <img
                    src="/static/uxcam-new-logo.svg"
                    alt="UXCam"
                    width="150px"
                  />
                </a>
              </div>
            </div>
          </div>
          <div className="content">
            <div className="container">
              <div className="row" style={{ marginTop: '-50px' }}>
                <div className="column">
                  <div className="text">
                    <span
                      className="main-number"
                      style={{
                        fontSize: '125px',
                        display: 'block',
                        lineHeight: 'normal',
                        marginBottom: '45px',
                      }}
                    >
                      {`${[403].includes(statusCode) ? statusCode : ''} Error!`}
                    </span>
                    <span
                      className="internal"
                      style={{
                        fontSize: '28px',
                        display: 'block',
                        margin: '20px 0 0 5px',
                      }}
                    >
                      {errorMessage || errorMessageGlobal}
                    </span>
                    <a
                      href={process.env.REDIRECT_URL}
                      className="ant-btn btn-home"
                    >
                      {errorMessage ? 'Back to dashboard ' : 'Reload the page'}
                    </a>
                  </div>
                </div>
                <div className="column">
                  <img
                    src="/static/error/illustration-server-down.svg"
                    className="illustration-img"
                    alt="Illustration server down"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      );
      break;
    case 302:
      PageContent = (
        <div className="error-content">
          <div className="external-header">
            <Menu selectedKeys="" mode="horizontal">
              <Menu.Item key="home" className="logo-box">
                <a href={process.env.REDIRECT_URL}>
                  <img src="/static/uxcam-logo-white.svg" alt="UXCam" />
                </a>
              </Menu.Item>
            </Menu>
          </div>
          <div className="error-message-box">
            <h1>302 Error</h1>
            <a href={process.env.REDIRECT_URL} className="ant-btn btn-home">
              Back to dashboard
            </a>
          </div>
          <div className="error-image">
            <img src="/static/404-uxcam.png" alt="404 UXCam" />
          </div>
        </div>
      );
      break;
    case 500:
      PageContent = (
        <div className="error-more error-500">
          <div className="header">
            <div className="container">
              <div className="externalheader">
                <a href={process.env.REDIRECT_URL}>
                  <img
                    src="/static/uxcam-new-logo.svg"
                    alt="UXCam"
                    width="150px"
                  />
                </a>
              </div>
            </div>
          </div>
          <div className="content">
            <div className="container">
              <div className="row" style={{ marginTop: '-50px' }}>
                <div className="column">
                  <div className="text">
                    <span className="main-number">500</span>
                    <br />
                    <span className="internal">Internal server error!</span>
                    <br />
                    <span className="error-message">
                      We are working towards creating something better. It won't
                      be long.
                    </span>
                  </div>
                </div>
                <div className="column">
                  <img
                    src="/static/error/illustration-server-down.svg"
                    className="illustration-img"
                    alt="Illustration server down"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      );
      break;
    case 406 :
      PageContent = (
        <div className="error-more custom-error already-login">
          <div className="header">
            <div className="container">
              <div className="externalheader">
                <a href={process.env.REDIRECT_URL}>
                  <img
                    src="/static/uxcam-new-logo.svg"
                    alt="UXCam"
                    width="150px"
                  />
                </a>
              </div>
            </div>
          </div>
          <div className="content">
            <div className="container">
              <div className="row" style={{ marginTop: '-50px', alignItems:'center' }}>
                <div className="column">
                  <div className="text">
                    <span
                      className="main-number"
                      style={{
                        fontSize: '40px',
                        display: 'block',
                        fontWeight: '600',
                        lineHeight: 'normal',
                        marginBottom: '45px',
                        paddingBottom: '20px',
                      }}
                    >
                      Already logged in!
                    </span>
                    <span
                      className="internal"
                      style={{
                        fontSize: '20px',
                        display: 'block',
                        margin: '20px 0 0 5px',
                        lineHeight: 'normal'
                      }}
                    >
                     You are already logged in with different account.
                    </span>
                    <div className='already-logged-btn'>
                    <a
                      href={process.env.REDIRECT_URL}
                      className="ant-btn btn-home"
                    >
                      Go to dashboard
                    </a>
                    <div className='log-out-btn'>
                    <span>or</span>
                    <div>
                    <button type='button' className='ant-btn-link' onClick={()=>Router.push('/logout')}>Log out</button>

                    </div>
                    </div>
                    </div>
                  
                  </div>
                </div>
                <div className="column">
                  <img
                    src="/static/error/illustration-server-down.svg"
                    className="illustration-img"
                    alt="Illustration server down"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      );
      break;
    case 404:
    default:
      PageContent = <FourHundredFour />
  }
  return (
    <div className="error-page">
      <MainHead headTitle={`${titleByEnv}Error`} />
      {PageContent}
    </div>
  );
};
Error.getInitialProps = async ({ res, jsonPageRes, query }) => {
  let statusCode = res?.statusCode || jsonPageRes?.status;
  let errorMessage;
  let data;
  if (query) {
    statusCode = +query.errorStatus;
    statusCode = statusCode === 400 ? 'custom' : statusCode;
    errorMessage = query.errorMessage;
    data = {
      statusCode,
      errorMessage,
    };
    return data;
  }
  return { statusCode };
};
export default Error;
