import React, { useEffect } from 'react'
import Router from 'next/router'
import { Menu } from 'antd'
import axios from 'axios'

const Maintenance = () => {
  const checkStatus = async () => {
    let response;
    try {
      response = await axios(`${process.env.API_URL}/auth/login`)
    } catch (error) {
      response = error
    }
    if (response?.message === 'Success') {
      Router.push('/dashboard')
    } else if (response?.response.status === 503) {
      setTimeout(() => {
        checkStatus()
      }, 120000)
    } else Router.push('/dashboard')
  }
  useEffect(() => {
    checkStatus()
  }, [])
  return (
    <div className='maintenance-wrapper'>
      <div className='error-page'>
        <div className='error-content'>
          <div className='external-header'>
            <Menu mode='horizontal'>
              <Menu.Item key='home' className='logo-box'>
                <a href={process.env.REDIRECT_URL}>
                  <img src='/static/uxcam-logo-white.svg' alt='UXCam' />
                </a>
              </Menu.Item>
            </Menu>
          </div>
          <div className='error-message-box'>
            <div className='loader-maintenance'>
              <img src='/static/maintenance.gif' alt='' />
            </div>
            <h1>System under maintenance</h1>
            <p>
              We'll be back up and running shortly. Thank you for your patience.
            </p>
            <a
              href='https://uxcam.com/contact'
              target='_blank'
              className='ant-btn btn-home' rel="noreferrer"
            >
              Contact Us
            </a>
          </div>
        </div>
      </div>
      <style>{`
              body{
               min-width: inherit!important;
               overflow: hidden;
              }
              .error-page{
                background-image: linear-gradient(0,#26013a -50%,rgba(69,74,253,.88) 70%);
                display: flex;
                color: #fff;
                text-align: center;
                flex-direction: column;
                height: 100vh;
                justify-content: center;
                position: relative;
              }
              .error-page p,
              .error-page h1{
                color: #fff;
              }
              .error-page h1{
                font-size: 4.5rem;
                font-weight: 700;
                margin-bottom: 30px;
              }
              .error-page p{
                font-size: 1.4rem;
                line-height: 32px;
                font-weight: 300;
                margin-bottom: 30px;
              }
              .error-page .error-content .error-message-box{
                padding-bottom: 0;
              }
              .error-page .btn-home{
                background-image: linear-gradient(#3adc91,#2ec8cc);
                color: #fff;
                padding: 8px 20px;
                height: auto;
                border: 0;
                border-radius: 50px;
                text-transform: uppercase;
                font-weight: 500;
              }
              .error-page .error-image {
                position: absolute;
                left: 0;
                right: 0;
                margin: auto;
                bottom: 0;
                line-height: 0;
              }
              .error-image img{
                max-width: 100%;
              }
              .external-header{
                position: absolute;
                top: 20px;
                right: 0;
                left: 0;
                margin: auto;
              }
              .external-header .ant-menu-horizontal{
                background-color: transparent;
                border:0;
              }
              .external-header .ant-menu-item{
                line-height: normal;
              }
              .external-header .logo-box img{
                width: 150px;
              }
              .external-header .ant-menu-item.logo-box{
                border:0 !important;
              }
              .loader-maintenance img{
                width: 300px;
              }
              .maintenance-wrapper{
                background: url('/static/main-banner-bg.jpg') fixed no-repeat;
                background-size: cover;
              }

            `}</style>
    </div>
  )
}

export default Maintenance
